.eon8-live-page .faq-answer {
  max-height: 0;
  overflow: hidden;
  padding: 0 20px;
  color: #6b7280;
  font-size: 14px;
  transition: all 0.4s ease;
}
.eon8-live-page .faq-item.active .faq-answer {
  max-height: 200px;
  padding: 0 20px 15px;
}
.eon8-live-page .faq-item.active .icon {
  transform: rotate(45deg);
}
.eon8-live-page .faq-item:hover {
  box-shadow: 0 10px 25px rgba(0,0,0,0.06);
}
.eon8-live-page .animate-faq {
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.6s ease;
}
.eon8-live-page .animate-faq.show {
  opacity: 1;
  transform: translateY(0);
}
.eon8-live-page .delay-1 { transition-delay: 0.1s; }
.eon8-live-page .delay-2 { transition-delay: 0.2s; }
.eon8-live-page .delay-3 { transition-delay: 0.3s; }
.eon8-live-page .delay-4 { transition-delay: 0.4s; }
.eon8-live-page .delay-5 { transition-delay: 0.5s; }
